export const productHasQuantity = (product: PurchaseFlowProduct | ProductCalendarItem) => {
  if (!product) {
    return false;
  }

  const dateSlotQuantity = "dateSlot" in product ? product.dateSlot?.quantity ?? 0 : 0;
  if (dateSlotQuantity > 0) {
    return true;
  }

  const timeSlotQuantity = "timeSlots" in product ? product.timeSlots?.[0]?.quantity ?? 0 : 0;
  if (timeSlotQuantity > 0) {
    return true;
  }

  return false;
};

export const isShippingFeeProduct = (product: Pick<NormalizedProduct, "glkProduct"> | undefined): boolean => {
  return product?.glkProduct?.productType === WebshopProductType.SHIPPING_FEE;
};

function getBookableInformation(
  subItems: Array<SubItemInCart>,
  productSlot: Pick<ResponseSlotItem, "isFullDay" | "slotFrom"> | undefined,
  productData: Exclude<NormalizedProduct["glkProduct"], undefined>,
) {
  // "BookableTimeSlot" products have both a date-slot and a time-slot. We are interested in the time-slot, which is a subItem.
  const activitySlot = productData.productType == "BookableTimeslot" ? subItems[0]?.slot : undefined;

  const slot = activitySlot ?? productSlot;
  if (!slot) {
    return undefined;
  }

  const onlyValidText = ECommerceHelper?.jetshop.onlyValidText;

  const isFullDay = slot.isFullDay;
  const timeSlotBegin = slot.slotFrom;
  if (!timeSlotBegin) {
    return undefined;
  }

  const begin = createDate(timeSlotBegin);

  return isFullDay
    ? `${onlyValidText ? onlyValidText + " " : ""}${DateHelper.toStringDDMonth(begin)}`
    : `${DateHelper.toStringDDMonth(begin)} - ${DateHelper.toStringTimeHHMM(begin)}`;
}

const flattenSubItems = (subItems: Array<CartResponseV2CartItem>): Array<CartResponseV2CartItem> =>
  subItems.flatMap((item) => [item, ...flattenSubItems(item.subItems ?? [])]);

function getGiftableInformation(data: CartResponseV2CartItem["data"], t: Translation) {
  const { deliverTo, scheduledDelivery, message } = data?.giftInformationV1 || {};

  const infoRows = [];

  if (deliverTo) infoRows.push(t("cartItemReceiverLabel", { receiver: deliverTo }));
  if (scheduledDelivery) {
    const deliveryTimeString = t("oClock", {
      date: scheduledDelivery.deliveryDate,
      time: scheduledDelivery.deliveryTime.slice(0, -3),
    });
    infoRows.push(
      t("cartItemScheduledDeliveryLabel", {
        deliveryTime: deliveryTimeString,
      }),
    );
  }
  // We want to limit the message length in the cart for better UX, but we still want to allow longer messages in the input, so we truncate it here instead of in the reducer
  if (message) infoRows.push(t("cartItemGreetingLabel", { greeting: truncateWithDots(message, 50) }));
  return infoRows;
}

const isCartItemDiscount = (discountItem: CartItemDiscount | NewItemDiscount): discountItem is CartItemDiscount => {
  return discountItem.DiscountType === "CartItemDiscount";
};

/**
 * Returns the redeemable data (voucher or promotion tier) associated with a cart item.
 * This can be zero, one or multiple redeemable data.
 */
export const redeemableDataForCartItem = (
  cartItem: CartResponseV2CartItem,
  discountItems: CartResponseV2["discountItems"],
  redeemableValidationResults: CartResponseV2["redeemableValidationResults"],
) => {
  return discountItems
    .filter(
      (discount) =>
        discount.DiscountType === "CartItemDiscount" && discount.discountedCartItemId === cartItem.cartItemGuid,
    )
    .filter(isCartItemDiscount)
    .map((discount) => {
      const validationResult = redeemableValidationResults.find(
        (result) => result.redeemableGuid === discount.redeemableGuid,
      );

      if (!validationResult) {
        return null;
      }

      if (validationResult.voucherCode) {
        return {
          type: "voucher" as const,
          id: discount.guid,
          amount: discount.amount.amountIncludingVat,
          code: validationResult.voucherCode,
        };
      }

      return {
        type: "promotionTier" as const,
        id: discount.guid,
        amount: discount.amount.amountIncludingVat,
        campaignName: validationResult.campaignName,
      };
    })
    .filter(isTruthy);
};

export const cartItemToItemInCart = (
  cartItem: CartResponseV2CartItem,
  productsById: ReadonlyMap<number, GlkBackedProduct>,
  discountItems: CartResponseV2["discountItems"],
  redeemableValidationResults: CartResponseV2["redeemableValidationResults"],
  t: Translation,
) => {
  const foundProduct =
    productsById.get(cartItem.productId) ??
    throwError(`Product with GLK-ID ${cartItem.productId} not found in static config products.`);

  const subItems = cartItem.subItems
    ? flattenSubItems(cartItem.subItems).map((subItem) => ({
        name: subItem.productName,
        slot: subItem.slot,
      }))
    : [];

  const bookableInformationMetadata = getBookableInformation(subItems, cartItem.slot, foundProduct.glkProduct);
  const giftableInformationMetadata = getGiftableInformation(cartItem.data, t);

  const cardOwner = cartItem.data?.cardHolderInformationV1
    ? t("owner", {
        firstName: cartItem.data.cardHolderInformationV1.firstName,
        lastName: cartItem.data.cardHolderInformationV1.lastName,
      })
    : undefined;

  // `ordinaryPrice` is presentation only, used to show previous price during discount campaigns (e.g. Black Week and
  // other holidays). Other discounts are applied by the discount engine, which is reflected in the `price` property.
  const ordinaryPrice = foundProduct?.glkProduct.ordinaryPrice ?? -1;
  const previousTotalPrice =
    ordinaryPrice !== -1 ? ordinaryPrice * cartItem.quantity : cartItem.price.amountBeforeDiscounts?.amountIncludingVat;

  const redeemableItems = redeemableDataForCartItem(cartItem, discountItems, redeemableValidationResults);

  return {
    id: cartItem.cartItemGuid,
    productId: cartItem.productId,
    name: cartItem.productName,
    price: cartItem.price.amount.amountIncludingVat,
    unitPriceIncludingVat: cartItem.price.unitPriceIncludingVat,
    quantity: cartItem.quantity,
    // minimumQuantity is marked as deprecated in the API, so it is always 1
    minimumQuantity: 1,
    previousTotalPrice,
    redeemableItems,
    visitorName: cartItem.visitorName,
    metadata: [bookableInformationMetadata, ...giftableInformationMetadata, cardOwner].filter(isTruthy),
    subItems,
    data: cartItem.data,
    deliveryType: cartItem.deliveryType,
    productType: foundProduct.glkProduct.productType,
  } satisfies ItemInCart;
};

export const myParkItemToItemInCart = (
  cartItem: CartResponseV2CartItem,
  rowItem: MyParkProductItemForCart,
  productsById: ReadonlyMap<number, GlkBackedProduct>,
  connectedDiscountRowItems: Array<MyParkProductItemForCart>,
  t: Translation,
) => {
  const foundProduct = productsById.get(rowItem.productId);

  const redeemableItems = connectedDiscountRowItems.map((discountRowItem) => ({
    type: "voucher" as const,
    id: discountRowItem.id.toString(),
    amount: discountRowItem.price ?? 0,
    code: discountRowItem.productName,
  }));

  const totalDiscountedAmount = redeemableItems.reduce((acc, item) => acc + item.amount, 0); //Will be 0 or negative
  const priceBeforeDiscounts = (rowItem.price ?? 0) * rowItem.quantity;
  const price = priceBeforeDiscounts + totalDiscountedAmount;

  const hasObliterationDate = !!rowItem.obliterateDate;

  const previousTotalPrice = totalDiscountedAmount < 0 ? priceBeforeDiscounts : hasObliterationDate ? price : undefined;

  return {
    id: rowItem.id.toString(),
    productId: rowItem.productId,
    name: foundProduct?.myParksName ?? rowItem.productName,
    previousTotalPrice: previousTotalPrice,
    price: hasObliterationDate ? undefined : price,
    unitPriceIncludingVat: rowItem.price ?? 0,
    quantity: rowItem.quantity,
    // minimumQuantity is marked as deprecated in the API, so it is always 1
    minimumQuantity: 1,
    redeemableItems,
    visitorName: undefined,
    metadata: [
      hasObliterationDate && t("obliteratedAtDate", [DateHelper.toStringYYYYMMDD(rowItem.obliterateDate)]),
    ].filter(isTruthy),
    subItems: [],
    data: undefined,
    deliveryType: cartItem.deliveryType,
    productType: foundProduct?.glkProduct.productType ?? WebshopProductType.STANDARD,
  } satisfies ItemInCart;
};

export const redeemableValidationErrorCodeToLabel = (errorCode: RedeemableValidationErrorCode): LabelKey => {
  switch (errorCode) {
    case RedeemableValidationErrorCode.RULE_EVALUATION_FAILED:
      return "redeemableError.ruleValidationFailed";
    case RedeemableValidationErrorCode.CAMPAIGN_INACTIVE:
      return "redeemableError.campaignInactive";
    case RedeemableValidationErrorCode.SKIPPED_DUE_TO_HIGHER_PRIORITY_REDEEMABLE_BREAKED:
      return "redeemableError.skippedHigherPriorityRedeemableBreaked";
    case RedeemableValidationErrorCode.SKIPPED_DUE_TO_NEVER_STACK:
      return "redeemableError.skippedNeverStack";
    case RedeemableValidationErrorCode.DISCOUNT_COULD_NOT_BE_APPLIED:
      return "redeemableError.discountCouldNotBeApplied";
    case RedeemableValidationErrorCode.REDEMPTION_LIMIT_EXCEEDED:
      return "redeemableError.redemptionLimitReached";
    case RedeemableValidationErrorCode.RESERVATION_FAILED:
      return "redeemableError.reservationFailed";
    case RedeemableValidationErrorCode.PROMOTION_TIER_NOT_FOUND:
      return "redeemableError.promotionTierNotFound";
    case RedeemableValidationErrorCode.VOUCHER_CODE_NOT_FOUND:
      return "redeemableError.voucherCodeNotFound";
    case RedeemableValidationErrorCode.REDEEMABLE_IS_BLOCKED:
      return "redeemableError.redeemableBlocked";
    case RedeemableValidationErrorCode.REDEEMABLE_INACTIVE:
      return "redeemableError.redeemableInactive";
    case RedeemableValidationErrorCode.REDEEMABLE_EXPIRED:
      return "redeemableError.redeemableExpired";
    default:
      return exhaustiveCheck(errorCode);
  }
};

export const usedVoucherCodesSummaryItems = (
  voucherCodes: CartResponseV2["voucherCodes"],
  redeemableValidationResults: CartResponseV2["redeemableValidationResults"],
) => {
  if (!isNonEmptyArray(voucherCodes)) {
    return [];
  }

  return sortBy(
    voucherCodes
      .map((code) => {
        const matchingRedeemable = redeemableValidationResults?.find((result) => result.voucherCode === code);

        if (!matchingRedeemable) {
          return null;
        }

        if (
          matchingRedeemable.result === ValidationResult.NOT_APPLICABLE ||
          matchingRedeemable.result === ValidationResult.SKIPPED
        ) {
          return {
            code,
            variant: "error" as const,
            description: matchingRedeemable.errorMessage
              ? {
                  type: "description" as const,
                  text:
                    matchingRedeemable.errorMessage[LanguageHelper.currentLocale] ?? matchingRedeemable.errorMessage.sv,
                }
              : {
                  type: "label" as const,
                  // We know this is fine since errorCode is always present when result is NOT_APPLICABLE or SKIPPED
                  // eslint-disable-next-line @typescript-eslint/no-non-null-assertion
                  labelKey: redeemableValidationErrorCodeToLabel(matchingRedeemable.errorCode!),
                },
          };
        }

        return {
          code,
          variant: "success" as const,
          description: {
            type: "description" as const,
            text: matchingRedeemable.campaignName,
          },
        };
      })
      .filter(isTruthy),
    (voucher) => (voucher.variant === "success" ? 0 : 1),
  );
};

export const getProductIds = (items: Array<{ productId?: number | null } | null | undefined> | null | undefined) =>
  items?.map((item) => item?.productId).filter(isTruthy) ?? [];

/**
 * Returns the first delivery type in the product's GLK data, or the fallback if none exists.
 *
 * @param product The product to get the delivery type from, usually a `NormalizedProduct`.
 * @param fallback The value to return if the product does not have a delivery type. (should usually be a `DeliveryType` but any type is allowed)
 */
export function getPrimaryDeliveryType<T>(
  product: Pick<NormalizedProduct, "glkProduct"> | undefined,
  fallback: T,
): DeliveryType | T {
  return product?.glkProduct?.deliveryTypes?.[0]?.deliveryType ?? fallback;
}
